// The consumer manifest (`bench_contract.yaml`, generated by `contract
// init`): which solution, which driver implements it and which scenarios it
// declares. Protocol values (runs, warm-ups, slack, timeouts) live in the
// package's methodology, NOT in the manifest — a consumer can pick
// scenarios but not redefine a metric (spec §7.2).
import 'dart:io';

import 'package:yaml/yaml.dart';

/// File name of the consumer manifest.
const String kManifestFileName = 'bench_contract.yaml';

/// Version of the generated templates (driver API + scenario files). Written
/// into the manifest by `init`; `contract verify` fails when the consumer's
/// generated files are older than the package's templates.
const int kTemplateVersion = 1;

/// All contract scenario ids (metric ids are identical to the scenario ids).
const Set<String> kContractScenarioIds = {
  'idle_zero',
  'idle_resources',
  'show_latency',
  'update_latency',
  'scroll_coupled',
  'active_heap',
  'hide_retention',
  'size',
};

/// Scenarios `init` enables by default (device-free runnable, no VM-service
/// requirement). The consumer adds heap scenarios + `size` when they apply.
const List<String> kDefaultScenarios = [
  'idle_zero',
  'show_latency',
  'update_latency',
  'scroll_coupled',
];

/// Runs per scenario in one `contract run` (methodology, spec §6): the noisy
/// wall-latency metrics repeat and the report reducer takes the median;
/// heap scenarios already median internally; structural ones are
/// deterministic.
int runsForScenario(String scenarioId) =>
    scenarioId == 'show_latency' ? 3 : 1;

/// One solution of a multi-library consumer (`libraries:` in the manifest).
///
/// Used by head-to-head consumers (e.g. the bench_compare package running
/// showcaseview + tutorial_coach_mark side by side): every entry gets its
/// own scenario directory and golden ref, sharing the scenario list.
class LibraryEntry {
  const LibraryEntry({
    required this.name,
    required this.driver,
    required this.driverClass,
    this.ref,
  });

  /// Solution name (report label, scenario directory name).
  final String name;

  /// Driver file path, relative to the consumer root.
  final String driver;

  /// Driver class name.
  final String driverClass;

  /// Golden ref override (e.g. `android-scv`); null → the CLI's --ref.
  final String? ref;
}

/// The consumer manifest.
class Manifest {
  Manifest({
    required this.library,
    required this.driver,
    required this.driverClass,
    required this.scenarios,
    this.contractDir = 'bench/contract',
    this.idleClasses = const [],
    this.libraries = const [],
    this.template = kTemplateVersion,
  });

  /// Solution name (report/README column label).
  final String library;

  /// Driver file path, relative to the consumer root (NOT under `lib/` — the
  /// driver runs in the flutter_test context, spec §3 / Р8).
  final String driver;

  /// Driver class name (e.g. `HintfulDriver`).
  final String driverClass;

  /// Solutions of a multi-library consumer; empty for the single-library
  /// shape (library/driver/driverClass).
  final List<LibraryEntry> libraries;

  /// The solutions to run: declared libraries, or the single shape.
  List<LibraryEntry> get entries => libraries.isNotEmpty
      ? libraries
      : [
          LibraryEntry(
            name: library,
            driver: driver,
            driverClass: driverClass,
          ),
        ];

  /// Scenario directory of [entry]: the shared [contractDir] for the
  /// single-library shape, one subdirectory per solution otherwise.
  String dirFor(LibraryEntry entry) => libraries.isEmpty
      ? contractDir
      : '$contractDir/${entry.name}';

  /// Declared scenario ids (subset of [kContractScenarioIds]).
  final List<String> scenarios;

  /// Directory of the generated contract files (driver API + scenario
  /// tests), relative to the consumer root.
  final String contractDir;

  /// Solution classes that must return to their baseline after warm-up +
  /// `hide()` (S1r `idle_resources`).
  final List<String> idleClasses;

  /// Template version the generated files were rendered with.
  final int template;

  /// Loads the manifest from [root] (default: current directory).
  static Manifest load(String root) {
    final file = File('$root/$kManifestFileName');
    if (!file.existsSync()) {
      throw FileSystemException('no $kManifestFileName in $root — run '
          '"dart run flutter_bench_contract:contract init" first');
    }
    final dynamic doc;
    try {
      doc = loadYaml(file.readAsStringSync());
    } catch (e) {
      throw FormatException('cannot parse $kManifestFileName: $e');
    }
    if (doc is! YamlMap) {
      throw FormatException('$kManifestFileName: expected a YAML map');
    }
    String str(String key, {String fallback = ''}) =>
        (doc[key] as String?) ?? fallback;
    List<String> list(String key) =>
        [for (final s in (doc[key] as List? ?? const [])) s as String];

    // Multi-library shape: `libraries: {name: {driver, driverClass, ref?}}`.
    // When present it fully replaces the single-library fields (which may be
    // absent); the consumer runs each entry against the same scenario list.
    final librariesDoc = doc['libraries'];
    final libraries = <LibraryEntry>[];
    if (librariesDoc != null) {
      if (librariesDoc is! YamlMap) {
        throw FormatException('$kManifestFileName: libraries must be a map '
            '{name: {driver, driverClass, ref?}}');
      }
      for (final entry in librariesDoc.entries) {
        final name = entry.key as String;
        final spec = entry.value;
        if (spec is! YamlMap || spec['driver'] is! String ||
            spec['driverClass'] is! String) {
          throw FormatException('$kManifestFileName: libraries.$name needs '
              'driver + driverClass');
        }
        libraries.add(LibraryEntry(
          name: name,
          driver: spec['driver'] as String,
          driverClass: spec['driverClass'] as String,
          ref: spec['ref'] as String?,
        ));
      }
    }

    return Manifest(
      library: str('library'),
      driver: str('driver'),
      driverClass: str('driverClass'),
      contractDir: str('contractDir', fallback: 'bench/contract'),
      scenarios: list('scenarios'),
      idleClasses: list('idleClasses'),
      libraries: libraries,
      template: doc['template'] is int ? doc['template'] as int : kTemplateVersion,
    );
  }
}
